package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim (a late entry when the period its due-by falls in is soft-closed), due by the business day its person's own terms (else the terms of their grade in force on
 *  that date, else the sheet's terms in force then) after its date, skipping weekends and the sheet's holidays, fixed now, and logs it as DRAFT by the user at its due then. */
public class SaveClaimAdded {
    public void save(@Val ClaimInput input, @Val Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, PeriodStore periods, HolidayStore holidays, Out<Claim> claim) {
        claim.set(add(input, person, store, settings, log, periods, holidays));
    }

    static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings, ClaimLogStore log,
            PeriodStore periods, HolidayStore holidays) {
        int terms = termsOf(person, input.date(), settings);
        LocalDate dueBy = holidays.businessDaysAfter(person.getSheetId(), input.date(), terms);
        Claim added = store.add(person.getSheetId(), person.getId(), input.amount(), input.date(), input.note(),
                input.corrects(), dueBy, terms, input.ref(), input.tags());
        if (periods.softOn(person.getSheetId(), dueBy)) {
            store.markLateEntry(added);
        }
        log.record(added, input.user());
        return added;
    }

    /** The terms a claim of the person dated {@code date} is due by: their own in force on the date, else their grade's in force
     *  on the date, else the sheet's then. */
    static int termsOf(Person person, LocalDate date, SettingStore settings) {
        Integer own = person.termsOn(date);
        return own != null ? own : settings.terms(person.getSheetId(), person.gradeOn(date), date);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.period.PeriodResponse;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** A claim belongs to the period its due-by falls in: the due-by fixed when it was added, which an edit, a
 *  re-dating or a move to another person leaves as it is (only a holiday added later re-fixes it). */
public final class ClaimPeriods {
    private ClaimPeriods() {
    }

    /** The due-by a claim of the person dated {@code date} would be fixed with, were it added now: its date
     *  the terms-th business day after it, for the terms it would get (see {@link SaveClaimAdded#termsOf}),
     *  skipping weekends and the holidays on the sheet now. */
    public static LocalDate dueByOf(Person person, LocalDate date, SettingStore settings, HolidayStore holidays) {
        return holidays.businessDaysAfter(person.getSheetId(), date, SaveClaimAdded.termsOf(person, date, settings));
    }

    /** Refuses opening the claim when the period it belongs to caps its open claims and the claim's person
     *  already has that many OPEN or PENDING claims in it. */
    public static void refuseCapped(PeriodStore periods, ClaimStore claims, Claim claim) throws InvalidSheetException {
        if (claim.getDueBy() == null) {
            return;
        }
        PeriodResponse period = periods.on(claim.getSheetId(), claim.getDueBy());
        if (period == null || period.cap() == null) {
            return;
        }
        int open = claims.countOpenDue(claim.getSheetId(), claim.getPersonId(), LocalDate.parse(period.from()),
                LocalDate.parse(period.to()));
        if (open >= period.cap()) {
            throw new InvalidSheetException("The period " + period.name() + " allows " + period.cap()
                    + " open claims per person");
        }
    }

    /** Refuses a claim due by {@code dueBy} when that falls in a closed period. */
    public static void refuseClosed(PeriodStore periods, String sheetId, LocalDate dueBy) throws InvalidSheetException {
        PeriodResponse closed = periods.closedOn(sheetId, dueBy);
        if (closed != null) {
            throw new InvalidSheetException("The period " + closed.name() + " is closed");
        }
    }
}

