import org.springframework.stereotype.Repository;

/** The settings kept per sheet, by key. A setting never set, or set blank, has no value. The settings
 *  that carry a figure (the clerk limit, the floor, the cap, the proof threshold, a grade's proof threshold, the note threshold, the review threshold, the terms, a grade's terms, a grade's grace days and the late
 *  percent) are dated: each value is recorded from a from-date, and the value in force on a date is the
 *  one with the latest from-date on or before it (none before every from-date, then the sheet's starting
 *  value). The policy date, the period numbering date, the entry date, the grace days, the escalation gap, the review SLA, the pot, the alert threshold, the parent sheet, the fiscal start month, the proof kinds and the permission matrix are not dated. */
@Repository
public class SettingStore {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String CAP = "cap";

    /** Above it a claim's due needs a proof before it is settled or approved. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The key of a grade's own proof threshold: proof-threshold-A, proof-threshold-B or proof-threshold-C (dated;
     *  blank for none, then the sheet's). */
    public static final String PROOF_THRESHOLD_PREFIX = "proof-threshold-";

    /** Whether the key is a grade's proof threshold. */
    public static boolean isGradeProofThreshold(String key) {
        return key.startsWith(PROOF_THRESHOLD_PREFIX) && GRADES.contains(key.substring(PROOF_THRESHOLD_PREFIX.length()));
    }

    /** The kinds of proof a claim above its proof threshold needs at least one of each of before it is settled
     *  or approved: listed comma separated (receipt, photo); blank for none, not dated. */
    public static final String PROOF_KINDS = "proof-kinds";

package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** The claim form's add, step by step, for a change that adds several claims at once (a paste). */
public final class ClaimAdding {
    private ClaimAdding() {
    }

    /** The claim form's rules on a claim typed for the person, before anything is stored: the claim as
     *  it would be stored. */
    public static ClaimInput check(String sheetId, Person person, ClaimRequest request, SettingStore settings,
            PeriodStore periods, ClaimStore claims, HolidayStore holidays) throws InvalidSheetException {
        ClaimInput input = ValidateClaim.check(sheetId, request, settings);
        ClaimPeriods.refuseClosed(periods, sheetId, ClaimPeriods.dueByOf(person, input.date(), settings, holidays));
        Retirement.refuseClaimDate(person, input.date());
        CheckCorrection.refuseUnsettled(claims, sheetId, person.getId(), input);
        CheckRef.refuseTaken(claims, sheetId, input, 0);
        return input;
    }

    /** Stores the checked claim as a DRAFT and records it as CLAIM_ADDED (and LATE_ENTRY for a late entry), then how it moved the figures. */
    public static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, PeriodStore periods, RollupService rollups, Audit audit, HolidayStore holidays) {
        var before = rollups.snapshot(person.getSheetId());
        Claim claim = SaveClaimAdded.add(input, person, store, settings, log, periods, holidays);
        AuditClaimAdded.record(input, person, claim, before, audit, rollups);
        return claim;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.holiday.HolidayStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim added for the person when the due-by it would be fixed with (the business day the terms it
 *  would get after its date) falls inside a closed period. */
public class CheckDatePeriod {
    public void check(@Val ClaimInput input, @Val Person person, SettingStore settings, PeriodStore periods,
            HolidayStore holidays)
            throws InvalidSheetException {
        ClaimPeriods.refuseClosed(periods, person.getSheetId(),
                ClaimPeriods.dueByOf(person, input.date(), settings, holidays));
    }
}

